"""Lesson 2.2 — Deterministic Schema Validation, Linked Data, and Canonical Citation.

One question per content page, in page order.
"""
from question_bank import Q

TOPIC = "Module_02_Cataloguing"
TITLE = "Deterministic Schema Validation, Linked Data, and Canonical Citation"

QUESTIONS = [
    Q("The Rule of the Machine: What \"Deterministic\" Really Means",
      "Yesterday you described ink, margins, and scribal hands by human judgement. Today the file meets a deterministic process. What makes a process deterministic?",
      correct=("Identical inputs run through explicit, rule-governed algorithms produce the identical, mathematically verifiable result every time.",
               "Correct. Determinism means zero variance: the same file in always yields the same verdict out, with no guessing and no creative license."),
      wrong=[("The process produces a result that a human editor has reviewed and approved before it is reported.",
              "Incorrect. Human review is interpretive judgement; the machine's verdict is produced by rules alone, without any editor in the loop."),
             ("The process returns a confidence score rather than a fixed pass or fail, leaving the decision to the scholar.",
              "Incorrect. A confidence score is a probabilistic output; determinism returns the same verdict, not a graded estimate."),
             ("The process silently repairs any mistakes it finds so the document always ends up valid.",
              "Incorrect. A validator reports conformance; it does not rewrite your file, and a repaired file would hide the error rather than certify the markup.")],
      note="Deterministic tools evaluate XML against unbending mathematical rules, ensuring that subjective human markup conforms to a rigorous, certified data standard."),

    Q("The Rulebook: How Schemas (RELAX NG) Police Your Markup",
      "Anyone can invent <code>&lt;vellum&gt;</code> or <code>&lt;animalSkin&gt;</code> and still have well-formed XML. What does a schema such as RELAX NG add to that?",
      correct=("It defines which tags are legal, where each may appear, how often it may repeat, and what format its attribute values must follow.",
               "Correct. Well-formedness only guarantees the syntax parses; the schema supplies the shared scholarly vocabulary that makes records interoperable."),
      wrong=[("It checks that every opening tag has a matching closing tag and that attribute values are quoted.",
              "Incorrect. Those are well-formedness rules enforced by any XML parser, and they are exactly what the invented tag already satisfies."),
             ("It stores a canonical list of approved manuscript descriptions that editors must copy from.",
              "Incorrect. A schema is a machine-readable grammar, not a catalogue of approved content; it constrains structure and vocabulary, not the facts you record."),
             ("It translates tags into a neutral human-readable language so that non-specialists can read the record.",
              "Incorrect. A schema governs validation; rendering for human readers is the job of stylesheets and publication tools.")],
      note="Basic XML syntax prevents computer crashes, but schemas (like RELAX NG) enforce the shared scholarly vocabulary that makes digital editions interoperable."),

    Q("Validating Your Hand-Written Header in VS Code",
      "You open your header in VS Code after adding an <code>xml-model</code> instruction, and the Problems panel stays empty. Why can an empty panel be a false negative?",
      correct=("It is empty because nothing inspected the file: if only Red Hat XML is installed, the RELAX NG schema is never checked.",
               "Correct. Red Hat XML validates DTD and XSD, not RELAX NG, so silence from the wrong extension proves nothing about your markup."),
      wrong=[("It is empty because VS Code suppresses schema diagnostics until the file is saved and committed to Git.",
              "Incorrect. The language server audits as you type; a save is not what triggers validation."),
             ("It is empty because the <code>xml-model</code> instruction tells VS Code to skip validation for hand-written files.",
              "Incorrect. The instruction is precisely what requests validation, by naming the schema and its schema language."),
             ("It is empty because the schema is downloaded only when you click Compile or upload the file to a server.",
              "Incorrect. There is no compile step and no upload; the editor fetches the schema in the background and checks continuously.")],
      note="By adding an `xml-model` processing instruction in VS Code, the editor downloads the schema and validates your markup in real time with line-by-line diagnostics."),

    Q("Structural Rules and Element Hierarchy in RNG",
      "RELAX NG reports <em>\"Element 'sourceDesc' is not allowed here\"</em> on a header that closes <code>&lt;fileDesc&gt;</code> before adding <code>&lt;sourceDesc&gt;</code>. What is the validator actually objecting to?",
      correct=("The sequence rule: <code>&lt;titleStmt&gt;</code>, <code>&lt;publicationStmt&gt;</code>, and <code>&lt;sourceDesc&gt;</code> must appear in that order inside <code>&lt;fileDesc&gt;</code>.",
               "Correct. The element is legal, but it has landed in the wrong place in the ordered hierarchy, which is what the message means."),
      wrong=[("The element does not exist in the TEI vocabulary and must be spelled differently.",
              "Incorrect. <code>&lt;sourceDesc&gt;</code> is a standard TEI element; a misspelling would produce a different message naming an unknown element."),
             ("<code>&lt;sourceDesc&gt;</code> is optional, so the schema treats any instance of it as surplus.",
              "Incorrect. In a manuscript header the element is required; the complaint is about its position, not its presence."),
             ("Cardinality has been exceeded, because <code>&lt;fileDesc&gt;</code> can contain only one child element.",
              "Incorrect. <code>&lt;fileDesc&gt;</code> must contain several children; cardinality limits repetition, not the number of distinct children.")],
      note="Schema validators check not only whether tags exist, but whether they appear in the correct sequence and within the correct parent container."),

    Q("Data Typing, Enumerations, and Attribute Constraints",
      "You write <code>&lt;supportDesc material=\"animal_skin\"&gt;</code> and <code>when=\"about 1050\"</code>. Which description of the schema's response is right?",
      correct=("Both fail: <code>@material</code> is checked against a closed enumeration and <code>@when</code> against an ISO 8601 date format.",
               "Correct. Datatypes police the value space and enumerations police the permitted keyword list, so fuzzy prose fails in an attribute even when a human would understand it."),
      wrong=[("Both pass, because a schema checks only element nesting and never the contents of attributes.",
              "Incorrect. Attribute datatypes and enumerations are exactly what a schema enforces; only element content is left comparatively free."),
             ("<code>@material</code> fails but <code>@when</code> passes, since dates are free text in TEI attributes.",
              "Incorrect. <code>@when</code> is constrained to ISO 8601; that is what makes chronology machine-computable."),
             ("<code>@when</code> fails but <code>@material</code> passes, since material values are project-defined.",
              "Incorrect. <code>@material</code> draws on an authorized vocabulary; only an institution's ODD can narrow it further, not a cataloguer's invention.")],
      note="Schemas enforce datatypes and closed vocabulary enumerations, preventing fuzzy text from breaking automated database calculations."),

    Q("Beyond Grammar: The Necessity of Schematron Business Logic",
      "A header declares <code>&lt;handDesc hands=\"1\"&gt;</code> and then lists <code>&lt;handNote xml:id=\"h1\"&gt;</code> and <code>&lt;handNote xml:id=\"h2\"&gt;</code>. RELAX NG raises no error. Why is Schematron needed here?",
      correct=("The contradiction is semantic, not grammatical: only rule-based validation can compare <code>@hands</code> with the number of <code>&lt;handNote&gt;</code> children.",
               "Correct. RELAX NG sees a permitted parent with permitted children; the logical clash between the count and the list is beyond a grammar."),
      wrong=[("Because RELAX NG cannot count repeated child elements, so it is unable to see the two <code>&lt;handNote&gt;</code> elements.",
              "Incorrect. Cardinality is a core RELAX NG feature; the problem is that \"one hand\" and \"two handNotes\" are two separate facts the grammar never compares."),
             ("Because <code>&lt;handNote&gt;</code> is not a legal child of <code>&lt;handDesc&gt;</code> and only Schematron knows the permitted hierarchy.",
              "Incorrect. Element hierarchy is exactly what RELAX NG enforces; if the nesting were illegal, the grammar would have caught it."),
             ("Because <code>xml:id</code> values are only validated by Schematron, so the duplicate identifiers went unchecked.",
              "Incorrect. Uniqueness of <code>xml:id</code> is not the issue here, and the two ids are in fact distinct.")],
      note="Grammatical schemas (RELAX NG) check tag structure, while rule-based validators (Schematron) catch real-world logical contradictions and broken cross-references."),

    Q("Writing Schematron Rules for Cross-References",
      "Your transcription reads <code>&lt;line hand=\"#h99\"&gt;</code> while the header declares only <code>h1</code> and <code>h2</code>. What does the Schematron assertion on <code>tei:line[@hand]</code> do about it?",
      correct=("It evaluates the XPath test comparing the pointer with the declared <code>@xml:id</code> values and fires its error message when no hand note matches.",
               "Correct. The assertion converts a dangling internal pointer into a clear, human-readable diagnostic instead of a downstream crash."),
      wrong=[("It repairs the pointer by rewriting <code>#h99</code> to the nearest declared hand identifier.",
              "Incorrect. Schematron asserts; it never edits the document, and guessing which hand was meant would fabricate evidence."),
             ("It rejects the file at parse time, because <code>@hand</code> values must be declared in the schema enumeration.",
              "Incorrect. <code>@hand</code> is an IDREF-style attribute; its target's existence is a document-level relationship, not a grammar rule."),
             ("It flags the error only when the referenced hand later appears in the transcription body.",
              "Incorrect. The assertion runs against the document as it stands; a pointer to a non-existent target fails immediately.")],
      note="Schematron audits internal pointers across your document, guaranteeing that every hand, scribe, and image reference points to an existing target."),

    Q("Customizing the TEI: The ODD (One Document Does-It-All) Philosophy",
      "The full TEI Guidelines offer over 500 elements. Why does a project define an ODD instead of validating against the whole of TEI?",
      correct=("The ODD selects the modules a project needs, removes unused elements, narrows attribute values, and documents the reasoning — and from it the schema is generated.",
               "Correct. One master document yields both the human-readable guidelines and the machine-readable RELAX NG schema, so rules and prose cannot drift apart."),
      wrong=[("The ODD is a pre-built schema downloaded from the TEI Consortium that each project edits by hand into a <code>.rng</code> file.",
              "Incorrect. An ODD is a project's own TEI-XML customization from which the <code>.rng</code> is compiled, not a downloaded file edited by hand."),
             ("The ODD restricts what a validator can report, suppressing errors about elements the project does not use.",
              "Incorrect. Subsetting removes elements from the vocabulary rather than suppressing messages about them."),
             ("The ODD replaces Schematron, using XPath assertions to enforce cross-element business rules.",
              "Incorrect. An ODD generates the grammar and its documentation; logical cross-element rules still come from Schematron.")],
      note="The TEI is customized for specific projects through ODD files, which generate both human documentation and strict RELAX NG schemas from a single source."),

    Q("Case Study: The Bodleian `msdesc.odd` Consolidated Schema",
      "The Bodleian holds manuscripts in dozens of languages, catalogued by hundreds of scholars. What does <code>msdesc.odd</code> enforce across that diversity?",
      correct=("Uniform repository naming, mandatory <code>&lt;supportDesc&gt;</code> declarations with controlled material vocabulary, standard foliation formats, and links to the library's own authority records.",
               "Correct. A consolidated schema is what makes records from many cataloguers comparable at the same technical standard."),
      wrong=[("A single shared language of description that cataloguers must translate their source material into before encoding.",
              "Incorrect. The schema standardizes encoding conventions; the manuscripts' own languages are unaffected."),
             ("A fixed template of manuscript descriptions that cataloguers fill in by substituting values into boilerplate prose.",
              "Incorrect. The ODD constrains structure and vocabulary, not a single prescribed text to be filled in."),
             ("A guarantee that every described manuscript has been digitized to a common imaging standard.",
              "Incorrect. The schema governs the TEI description, which can be written for an undigitized manuscript as easily as a digitized one.")],
      note="Major archives like Oxford's Bodleian Library rely on customized TEI schemas to ensure consistent cataloguing across thousands of historical manuscripts."),

    Q("Case Study: Bibliotheca Laureshamensis and the ENRICH Schema",
      "The library of Lorsch was dispersed during the Reformation and the Thirty Years' War; its codices now sit in 73 libraries in 12 countries. How was it virtually reunified?",
      correct=("Participating libraries each catalogued their holdings under the shared ENRICH schema, so one portal could ingest records from 73 independent institutions.",
               "Correct. Interoperable metadata, not physical movement, is what reassembled the collection on a single screen."),
      wrong=[("The surviving codices were loaned or transferred back to Lorsch so they could be catalogued together in one place.",
              "Incorrect. The manuscripts remain dispersed in their holding institutions; the reunification is entirely digital."),
             ("Each library's records were converted by hand into one common format by a central cataloguing team.",
              "Incorrect. The point of a shared schema is that records are already interoperable, so no bespoke conversion is needed."),
             ("A single large manuscript database was purchased and all competing records were discarded.",
              "Incorrect. The project aggregates the participating libraries' own descriptions rather than replacing them.")],
      note="The virtual reconstruction of Lorsch Abbey demonstrates how shared XML schemas allow globally scattered manuscript collections to be digitally reunited."),

    Q("Breaking Out of the Silo: Why XML Needs Linked Open Data",
      "Your validated header records <code>&lt;origPlace&gt;Antigonish&lt;/origPlace&gt;</code>. Another cataloguer's file records <code>&lt;origPlace&gt;Town of Antigonish&lt;/origPlace&gt;</code> for the same town. What is the problem, and what is the remedy?",
      correct=("To the machine both are uninterpreted character strings naming no shared entity, so each name must be linked to a persistent identifier for the place.",
               "Correct. The file is structurally sound and semantically isolated; moving from strings to things is what lets two repositories' records connect."),
      wrong=[("The two spellings are a validation failure, and the schema should be customized to accept both variants.",
              "Incorrect. Both files validate; the schema constrains markup, and widening it would not tell a machine that the two names denote one city."),
             ("A search engine can never find either string, so the names must be indexed in a full-text search service.",
              "Incorrect. Simple keyword search would find them; the failure is automated reasoning about identity, not retrieval."),
             ("One spelling is historically wrong and should be corrected to the form the source document uses.",
              "Incorrect. Editing the name may well be right for the transcription, but it does nothing to link the record to a shared entity.")],
      note="Clean XML markup creates structured documents, but Linked Open Data connects the entities inside those documents to global knowledge networks."),

    Q("Speaking in Triples: The Resource Description Framework (RDF)",
      "An RDF statement about your witness reads: subject <code>https://www.wikidata.org/wiki/Q3350</code>, predicate <code>http://purl.org/dc/terms/spatial</code>, object <code>https://www.geonames.org/...</code>. What is the role of each part?",
      correct=("The subject is the thing being described, the predicate names the relationship, and the object is the value — all three named by URI rather than by prose words.",
               "Correct. A triple is the subject-predicate-object sentence of Linked Data, and URIs let two machines read it without ambiguity."),
      wrong=[("The subject is the property, the predicate is the value, and the object is the vocabulary that defines the property.",
              "Incorrect. That reverses the roles; the predicate is the property and the object is the value assigned to it."),
             ("The subject is a literal string, the predicate is a natural-language verb such as \"was copied in\", and the object is a URI.",
              "Incorrect. RDF deliberately replaces fuzzy English words with URIs for every position, including the predicate."),
             ("The three parts are the XML element, its attribute, and its text content, serialized as URIs.",
              "Incorrect. Those are components of an XML tree; a triple is a graph edge with no dependence on XML markup.")],
      note="RDF models knowledge as unambiguous three-part statements (Subject to Predicate to Object), connecting web identifiers into global knowledge graphs."),

    Q("From Strings to Real Things: Authority Control in TEI",
      "How do you convert <code>&lt;repository&gt;Nova Scotia Archives&lt;/repository&gt;</code> in your header into an authority-controlled reference?",
      correct=("Add a <code>@ref</code> attribute carrying the institution's canonical URI, keeping the human-readable name as the element's text.",
               "Correct. The reader still sees the familiar name while the machine follows the URI to the authority record for the institution."),
      wrong=[("Replace the repository name with the authority URI, since only the URI is machine-actionable.",
              "Incorrect. Dropping the readable text removes what a human reader needs, and authority control keeps both layers."),
             ("Add the URI in a <code>&lt;note&gt;</code> beside the element so the reference is preserved without altering the markup.",
              "Incorrect. A note is prose; automated tools follow <code>@ref</code>, not free text inside a note."),
             ("Wrap the repository name in a <code>&lt;ptr&gt;</code> element nested inside <code>&lt;repository&gt;</code>.",
              "Incorrect. The standard mechanism here is <code>@ref</code> on the element that names the entity, not a nested pointer element.")],
      note="By adding `ref` attributes to names and places, your TEI Header links human-readable text to permanent machine-readable authority records."),

    Q("The Authority Registers: A General Layer and a Tradition-Specific Layer",
      "Which statement about authority registers matches how this course divides them?",
      correct=("Registers such as VIAF, Wikidata, Library of Congress, and Getty apply broadly, while a tradition-specific register governs only documents of its own tradition.",
               "Correct. Choosing a register built for the wrong tradition is a methodological error, not a harmless extra link."),
      wrong=[("General registers cover institutions and tradition-specific registers cover physical objects, and between them every document is fully covered.",
              "Incorrect. The split is by tradition, not by object type, and no register set is automatically complete for a document."),
             ("Any register may be used for any document, provided the identifier resolves to a record of some kind.",
              "Incorrect. A resolving identifier from the wrong register describes the wrong kind of object, and a link that loads is not evidence of relevance."),
             ("Tradition-specific registers are older and less reliable, so general registers should be used in preference wherever possible.",
              "Incorrect. The two layers answer different questions; the tradition-specific register is often the only one that governs the object.")],
      note="Authority control has a general layer (VIAF, Wikidata, LC, Getty) that works for almost anything, and a tradition-specific layer that does not transfer between traditions. Identify both, justify why each register governs your document, and verify by reading the record rather than by checking that the link loads."),

    Q("Mapping Manuscript Migrations (MMM): Harmonizing Global Data",
      "MMM combined over 500,000 records from the Schoenberg Database, Bibale, and the Oxford medieval manuscripts portal. What made that harmonization possible?",
      correct=("Each institution's metadata was converted into RDF triples and linked through shared authority identifiers, so provenance events across collections could be joined.",
               "Correct. Shared authority IDs are the join key that turns three separate catalogues into one queryable graph of manuscript movement."),
      wrong=[("The three databases were merged into a single centralized catalogue with one institution as its maintainer.",
              "Incorrect. The source databases remain separate; MMM links across them rather than absorbing them."),
             ("Each institution rewrote its records to a single agreed prose template for provenance statements.",
              "Incorrect. Harmonization operates on structured triples, not on standardizing the wording of prose descriptions."),
             ("The records were matched by comparing manuscript titles and dates with a string-similarity algorithm.",
              "Incorrect. Shared identifiers, not approximate string matching, are what link records to the same entity reliably.")],
      note="The Mapping Manuscript Migrations project proves how linking local catalog records to shared RDF authorities unlocks global historical patterns of manuscript trade and provenance."),

    Q("Wikibase and Knowledge Graphs for Codicology",
      "A 14th-century merchant's shopping list turns up scribbled on a flyleaf of your manuscript. Why is a knowledge graph better placed to record this than a fixed relational table?",
      correct=("A graph connects any entity to any other through typed properties, so an unexpected kind of detail needs a new statement rather than a new column.",
               "Correct. The model is a living web of nodes and edges, and typed properties let codicological discoveries be added as they arise."),
      wrong=[("A graph stores all values as free text, so unusual details can be typed in without designing a schema for them.",
              "Incorrect. Graph statements are structured subject-predicate-object claims, not unstructured text fields."),
             ("A graph is simply a faster database because it keeps related records adjacent on disk.",
              "Incorrect. Performance is not the argument; the difference is how the data model accommodates unforeseen relationships."),
             ("A graph requires no identifiers, so the shopping list can be recorded without naming the manuscript it sits in.",
              "Incorrect. Entities and properties in a knowledge graph are identified, which is what makes the claims queryable and linkable.")],
      note="Knowledge graphs represent complex, interconnected manuscript histories as living networks of entities and relationships, easily enriched by TEI metadata."),

    Q("Link Rot and 404s: Why Regular Web Links Fail Ancient Documents",
      "Your edition cites a facsimile at <code>https://www.somelibrary.edu/special-collections/greek/mss/box4/image23.jpg</code>. Why is this an unacceptable citation for scholarship that should last?",
      correct=("The URL names a location on one server, so a reorganization, rename, or rebranding turns the citation into a 404 with nothing to fall back on.",
               "Correct. Link rot is the predictable consequence of citing a temporary address rather than an identifier independent of it."),
      wrong=[("The URL is too long and complex to be printed accurately in a journal article.",
              "Incorrect. Length is not the defect; even a short URL dies with the server path it encodes."),
             ("The URL points to an image rather than to a text, and images cannot be cited in scholarly editions.",
              "Incorrect. Images are cited routinely; the problem is the instability of the address, not the medium."),
             ("The URL lacks a file extension that identifies the resource type to a resolver.",
              "Incorrect. The extension is present, and in any case it would not make the address survive a server reorganization.")],
      note="Standard web URLs are fragile and prone to link rot; scholarly editions require persistent, location-independent citation architectures that outlive server reboots."),

    Q("Citing a Structure, Not a File",
      "A treaty survives as a printed proclamation, as manuscript copies in council registers, and as a transcription sent to London. What does this case show about citation?",
      correct=("The text has a structure — articles and clauses — independent of whichever carrier transmits it, and citing that structure outlives any one carrier.",
               "Correct. Separating the logical structure from the physical carrier is what makes a citation survive the shelfmark, the server, and the file path."),
      wrong=[("The treaty's text differs in each carrier, so a citation must specify which of the three versions is being quoted.",
              "Incorrect. Multiple carriers of one text is the normal case; the principle at issue is citing the structure they share."),
             ("The printed proclamation is the authoritative carrier, so citations should follow its pagination.",
              "Incorrect. Print pagination is exactly the location-dependent label that a durable citation avoids."),
             ("Only the manuscript register copies count as archival objects, so only they can be given identifiers.",
              "Incorrect. Identifiers are assigned to whatever the responsible institution holds, and to the work as well as the carrier.")],
      note="Distinguish the text's logical structure from the physical carrier that transmits it — that distinction is what lets a citation outlive the shelfmark, the server, and the file path."),

    Q("Canonical Citation: Giving Your Object a Stable Address",
      "Why is citing a manuscript by its shelfmark alone a fragile practice?",
      correct=("Shelfmarks change when libraries reclassify or collections move, so a citation built on one breaks at the next revision.",
               "Correct. A canonical citation therefore adds an identifier assigned by an authority and persistent across such changes."),
      wrong=[("Shelfmarks are assigned by cataloguers rather than by the holding institution, so they carry no authority.",
              "Incorrect. Shelfmarks are assigned by the holding library; the defect is their mutability, not the absence of an authority."),
             ("Shelfmarks are not unique, since two libraries may use the same call number for different manuscripts.",
              "Incorrect. A shelfmark is unique within its repository, and citations normally name the repository as well."),
             ("Shelfmarks describe the physical object, whereas scholarship needs to cite the abstract work.",
              "Incorrect. Citing the object is legitimate and often necessary; the problem is that the label pointing to it is not stable.")],
      note="Cite your object by a persistent identifier as well as by its shelfmark, because shelfmarks change and scholarship has to outlast them."),

    Q("Three Citation Systems, Three Traditions",
      "Which grouping correctly pairs each student's document with the citation system its holding institution uses?",
      correct=("The French act with an Archives nationales cote and, if digitised, a Gallica ARK such as <code>ark:/12148/...</code>; the Dickinson manuscript with a Houghton call number; and the treaty with a Nova Scotia Archives record-group reference.",
               "Correct. Three traditions, three systems, and in each case the identifier is copied in the syntax the issuing institution writes."),
      wrong=[("All three with an ARK, since ARK is the general-purpose persistent identifier scheme for cultural objects.",
              "Incorrect. ARK is a scheme many institutions could mint, but Houghton and the Nova Scotia Archives cite their holdings in their own forms."),
             ("The French act with a call number, the Dickinson poem with an archival record-group reference, and the treaty with an ARK.",
              "Incorrect. That is the pairing inverted: call numbers belong to library manuscript series and record groups to archives."),
             ("All three with a normalized form, converting each identifier to a single consistent pattern so records can be compared.",
              "Incorrect. Normalizing an identifier renames it, and an identifier is a name; the instruction is to copy its syntax exactly.")],
      note="ARK, library call number, and archival reference number are three different citation systems serving three different traditions — use the one your holding institution uses, and copy its syntax exactly rather than normalising it."),

    Q("Reading a Record, Not Just Finding It",
      "The Gallica record for <code>ark:/12148/bpt6k9690620k</code> reports the format as <em>67 pièces en 1 vol. in-4&deg;</em>. Why does that field matter to your catalogue entry?",
      correct=("It warns that the object is a <em>recueil</em> of many pieces, so cataloguing the volume as one act would misdescribe what you are holding.",
               "Correct. Reading the record is what turns an identifier into knowledge, and mismatches with your expectations are findings rather than obstacles."),
      wrong=[("It confirms that the volume contains exactly one document, since a single volume is a single catalogue item.",
              "Incorrect. One volume may bind many pieces, which is precisely what the field is telling you."),
             ("It has no bearing on the header, since physical format belongs to the holding library's internal records.",
              "Incorrect. Format and extent are facts a TEI header records, and they are also facts you can check."),
             ("It means the ARK identifies the individual piece rather than the volume, so no further disambiguation is needed.",
              "Incorrect. The ARK identifies the digitized object described by that record, which the format field shows to be a collected volume.")],
      note="An identifier is a pointer, not a fact. Open the record and read its fields, because the metadata inside is what goes into your header — and mismatches between the record and your expectations are findings, not obstacles."),

    Q("Dating: Where Records Mislead",
      "You are dating a Dickinson poem and a French act of 1791, and a watermark on the paper reads 1771. Which statement reflects the lesson's caution about dates?",
      correct=("A date in a catalogue record may be an editorial attribution rather than an authorial statement, and a watermark dates the paper rather than the document.",
               "Correct. Ask of every date whether it is authorial, editorial, or a record of something else, and record the uncertainty instead of flattening it."),
      wrong=[("The watermark gives a secure date for the paper and therefore for the poem written on it.",
              "Incorrect. Dating the paper does not date the writing, and Dickinson's poems were rarely dated by their author at all."),
             ("The Ancien Régime year-start-style trap applies to the 1791 act, so its year may need adjusting.",
              "Incorrect. That trap cannot reach a document of 1791: the French year had begun on 1 January since the édit de Roussillon took full effect in 1567. Knowing the period tells you which trap is live — applying a rule from the wrong century is its own kind of confident error."),
             ("A printed proclamation's date of printing is the date of the agreement it publishes.",
              "Incorrect. A printing date is not the date of the event recorded and certainly not the date of the agreement published.")],
      note="Ask of every date whether it is authorial, editorial, or a record of something else — and record the uncertainty rather than flattening it, because a confident wrong date is exactly the failure your workshop is about."),

    Q("Recording the Citation in Your Header",
      "Which entry records the treaty's reference number correctly in <code>&lt;msIdentifier&gt;</code>?",
      correct=("<code>&lt;idno type=\"reference\"&gt;RG 1 volume 430 number 2&lt;/idno&gt;</code>, with the object's status given separately in a typed <code>&lt;note&gt;</code>.",
               "Correct. The <code>@type</code> says which kind of identifier this is, and the reference number alone never states whether the object is an original, a copy, or a printed edition."),
      wrong=[("<code>&lt;idno&gt;RG 1 volume 430 number 2&lt;/idno&gt;</code>, since the number's form makes its kind self-evident.",
              "Incorrect. A bare <code>&lt;idno&gt;</code> tells a reader nothing about which kind of identifier it is, which is what <code>@type</code> is for."),
             ("<code>&lt;idno type=\"reference\"&gt;RG1/430/2&lt;/idno&gt;</code>, normalizing the reference into a consistent delimited form.",
              "Incorrect. Renaming the identifier breaks it; the reference must be copied exactly as the issuing institution writes it."),
             ("<code>&lt;repository ref=\"RG 1 volume 430 number 2\"&gt;Nova Scotia Archives&lt;/repository&gt;</code>, placing the citation on the holding institution.",
              "Incorrect. A reference number identifies the object, not the repository, and <code>@ref</code> carries an authority URI rather than an archival citation.")],
      note="Record each identifier in its own `<idno>` with a `type`, put authority URIs in `ref` on the element they identify, and state the object's status separately — because the identifier alone does not say what kind of thing you are holding."),

    Q("Hands-On in VS Code: Connecting to the Schema",
      "What are the concrete steps of today's lab in VS Code, before any enriching of the header?",
      correct=("Copy <code>03a_Lesson_2.1_Primary_Witness_Header.xml</code> to <code>03a_Lesson_2.2_Validated_Witness_Header.xml</code> and add the <code>xml-model</code> instruction at the top so the editor audits it.",
               "Correct. The copy preserves Tuesday's ground truth while the processing instruction connects the working file to the official schema."),
      wrong=[("Validate the file by uploading it to an institutional server, then download the corrected version.",
              "Incorrect. The language server validates locally and continuously; there is no upload step."),
             ("Re-type the header from scratch so that the schema's defaults are applied as you go.",
              "Incorrect. Re-typing discards the human ground truth the whole exercise depends on."),
             ("Download the RELAX NG schema by hand and paste it into the header so the rules travel with the file.",
              "Incorrect. The schema is referenced by the <code>xml-model</code> instruction, not embedded in the document.")],
      note="Copy your hand-written header to `03a_Lesson_2.2_Validated_Witness_Header.xml`, add the `xml-model` processing instruction, and let VS Code audit your markup."),

    Q("Slaying the Red Squiggles: Reading Validator Error Messages",
      "VS Code reports <em>\"Attribute 'material' has invalid value\"</em> on <code>&lt;supportDesc material=\"vellum\"&gt;</code>. What is the correct fix?",
      correct=("Change the value to one the schema permits for that attribute — the message is telling you the value violates an enumeration.",
               "Correct. Reading the message precisely is what separates an enumeration violation from a sequence mistake or an unclosed tag."),
      wrong=[("Delete the <code>@material</code> attribute, since a description cannot legally specify a material.",
              "Incorrect. The attribute is legal and expected; it is the value that is outside the permitted list."),
             ("Reorder <code>&lt;supportDesc&gt;</code> within <code>&lt;objectDesc&gt;</code>, because the message means the element is out of sequence.",
              "Incorrect. A sequence problem produces \"is not allowed here\"; this message names an attribute value."),
             ("Insert the missing closing tag for <code>&lt;supportDesc&gt;</code>, which is what has made the value unreadable.",
              "Incorrect. An unclosed element produces a termination message naming the element type.")],
      note="Read schema error messages carefully to identify sequence mistakes, unclosed tags, or illegal attribute values, resolving them one by one."),

    Q("Enriching Your Header with Authority URIs",
      "You need a URI for the place of issue on your document. What does the lesson recommend?",
      correct=("Use the register appropriate to the place in question, open the candidate record, and confirm its name, dates, and description match the entity you intend.",
               "Correct. Verification means reading the record's content; a register that returns a page for a non-existent identifier makes a loading link worthless as evidence."),
      wrong=[("Use whichever geographic register returns a result first, since any gazetteer entry for a place name is better than none.",
              "Incorrect. The wrong register may describe a different entity or a different kind of place entirely, and coverage is not correctness."),
             ("Use a general ancient-geography register for every place, so that all your place references come from one system.",
              "Incorrect. An ancient-geography register will not help with a modern town, so the register has to fit the document."),
             ("Cite the holding institution's own web page for the place, since the institution is the authority for its own records.",
              "Incorrect. An institution's page about a place is not an authority record for that place, and it does not give you a shared identifier.")],
      note="Enrich your repository and place of issue with authority URIs from the register appropriate to your document's tradition, and verify each by reading the record's content rather than by confirming the link resolves."),

    Q("Adding Your Canonical Citation",
      "You have an ARK, a call number, or an archival reference, plus a general-layer authority URI. What rule governs writing them into the header?",
      correct=("Each identifier goes in its own typed <code>&lt;idno&gt;</code>, the object's status is recorded in a <code>&lt;note&gt;</code>, and every identifier is copied in the exact syntax the issuing institution uses.",
               "Correct. An identifier is a name, so normalising its punctuation or spacing renames it and breaks it."),
      wrong=[("Each identifier is recorded once, in a canonical normalized form, so that your edition's citations are internally consistent.",
              "Incorrect. Internal consistency is achieved at the cost of correctness: the identifier must match the institution's form, not your house style."),
             ("Identifiers are recorded in the <code>&lt;encodingDesc&gt;</code>, keeping <code>&lt;msIdentifier&gt;</code> for the manuscript's own name and shelfmark.",
              "Incorrect. The identifiers of the object belong in <code>&lt;msIdentifier&gt;</code>, which is what the lesson's markup shows."),
             ("The status of the object is omitted, since a reference number identifies the object precisely enough on its own.",
              "Incorrect. A reference number tells you the volume but not whether the item is an original, a copy, or a printed edition.")],
      note="Put each identifier in its own typed `<idno>`, add the object's status as a `<note>`, and copy the syntax exactly as the issuing institution writes it."),

    Q("Seeing Your Header as Linked Data",
      "When semantic tools ingest your header, they read it as a series of checkable claims. What follows from that for your workshop?",
      correct=("The structure can validate perfectly while a claim is false — a repository URI pointing at another institution, say — and only a human comparing the claim against the record catches it.",
               "Correct. Your header is a set of claims about real entities, which is exactly why an AI-generated header can be confidently, structurally valid, and wrong."),
      wrong=[("Validating the file is sufficient quality control, because a schema-valid header cannot contain false statements.",
              "Incorrect. A schema can check that a URI is well formed but has no access to which institution it names."),
             ("The claims are only as reliable as the triples extracted from them, so the extraction step must be repeated annually.",
              "Incorrect. Re-extraction would reproduce the same claims from the same file; the risk lies in the claims themselves."),
             ("Claims become checkable only once the header is published to a triple store rather than stored as a file.",
              "Incorrect. Checkability does not depend on publication; the assertions are checkable as soon as they are written.")],
      note="Your header is a set of checkable claims about real entities — which is exactly why an AI-generated header can be confidently, structurally valid, and wrong."),

    Q("The Stage Gate: Achieving a Zero-Error Audit in Git",
      "Your header still shows one schema violation when you are ready to commit. What does the stage gate require?",
      correct=("Resolve it until the Problems counter reads zero errors and zero warnings, then commit and push the validated file with the error count noted in the message.",
               "Correct. Deterministic validation is an all-or-nothing threshold, and the commit message documents that the automated audit passed."),
      wrong=[("Commit the file anyway and note the outstanding violation in the message, since the work can be corrected later.",
              "Incorrect. A single remaining violation means the document cannot be ingested by the downstream pipelines that follow."),
             ("Suppress the warning in the editor so the counter reads zero, then commit the suppressed file.",
              "Incorrect. Suppressing a diagnostic changes the report, not the document, and leaves the defect in place."),
             ("Commit only once the file also passes every Schematron rule the project might later adopt.",
              "Incorrect. The gate is the active schema reported in the Problems panel, not an open-ended set of future rules.")],
      note="Verify that VS Code reports 0 errors and 0 warnings, then commit your validated header to Git as your certified deterministic milestone."),

    Q("Synthesis: The Three-Step Cycle in Action",
      "Why does the course insist on manual ground truth plus deterministic validation before any AI is introduced?",
      correct=("Together they establish a certified baseline against which a probabilistic model's output can be measured for precision and recall.",
               "Correct. Without a verified baseline there is nothing to score the AI against, and the hallucinations it invents cannot be demonstrated."),
      wrong=[("Because the AI cannot process a file that has not first passed schema validation.",
              "Incorrect. A model will process any text; the baseline exists to judge the output, not to feed it."),
             ("Because the manual and deterministic stages together produce a description more accurate than any automated tool can achieve.",
              "Incorrect. The argument is methodological: the two stages define what correct means so that automated output can be evaluated."),
             ("Because the deterministic stage replaces the human judgement exercised on the first day.",
              "Incorrect. The two steps are complementary — human interpretation, then machine verification — and neither replaces the other.")],
      note="Manual ground truth plus deterministic validation creates the rigorous foundation needed to evaluate and control probabilistic AI on Friday."),
]
